mapper.insert:
 
	  
	  	SELECT ISNULL(MAX(CONVERT(INT,SACD)),0) + 1 SACD FROM SAWON_MST
	  
		INSERT INTO SAWON_MST (
		  		 GROUPCD   
		         ,GROUPNAME   
		         ,COMCD   
		         ,COMNAME
		         ,POSITIONCD   
		         ,POSITION   
		         ,SANAME   
		         ,TELNO   
		         ,HANDNO   
		         ,SACD   
		         ,SABUN  
		         ,PRDATETIME
		         ,PRUSERID
		         ,TOISA
		)
		SELECT 
		  		#{USER.GROUPCD}   
		        ,#{USER.GROUPNAME}   
		        ,#{USER.COMCD}   
		        ,#{USER.COMNAME}   
		        ,''   
		        ,#{POSITION}
		        ,#{SANAME}
		        ,''
		        ,#{HANDNO}
		        ,#{SACD}
		        ,#{SABUN}
		        ,DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		        ,#{USER.USERID}
		        ,'N'
		FROM DUMMY 
		WHERE NOT EXISTS (SELECT 1 FROM SAWON_MST C WHERE SACD = #{SACD} )

mapper.update:
 
		UPDATE SAWON_MST SET
				POSITION = #{POSITION}
				,SANAME = #{SANAME}
				,TELNO = #{TELNO}
				,HANDNO = #{HANDNO}
				,SABUN = #{SABUN}
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE SACD = #{SACD}

 
		UPDATE SAWON_MST SET
				TOISA = 'Y'
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE SACD = #{SACD}
